Use `pg` (node-postgres) with `Pool`:

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Pool sizing
  max: 20,                    // max connections
  min: 2,                     // keep alive connections
  idleTimeoutMillis: 30000,   // close idle connections after 30s
  connectionTimeoutMillis: 5000, // fail fast if can't connect in 5s
  // Per-query timeout
  statement_timeout: 10000,   // 10s query timeout
  query_timeout: 10000,
});

// Catch idle client errors (network drops, DB restart)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});
```

**Query pattern with proper cleanup:**

```javascript
async function query(text, params) {
  const client = await pool.connect();
  try {
    const result = await client.query(text, params);
    return result;
  } catch (err) {
    // Log with query context, rethrow
    console.error('Query failed:', { text, err: err.message });
    throw err;
  } finally {
    client.release(); // always release, even on error
  }
}
```

**Transaction pattern:**

```javascript
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('INSERT INTO ...', [...]);
  await client.query('UPDATE ...', [...]);
});
```

**Graceful shutdown:**

```javascript
process.on('SIGTERM', async () => {
  await pool.end(); // drains pool, waits for in-flight queries
  process.exit(0);
});
```

Key points:
- `connectionTimeoutMillis` fails fast when pool exhausted — catches traffic spikes early
- `idleTimeoutMillis` prevents stale connections after DB-side timeouts (e.g. RDS default 8hr)
- `statement_timeout` set at pool level applies to all queries; override per-client if needed
- Always `release()` in `finally` — leaked clients exhaust pool silently
